input.command:
cat > /tmp/v.js <<'EOF'
const page = await browser.getPage("v");
const errs=[];
page.on("console",m=>{if(m.type()==="error")errs.push(m.text())});
page.on("pageerror",e=>errs.push("PE "+e.message));
await page.goto("file://"+process.cwd()+"/index.html");
await page.waitForTimeout(4000);
for (const sel of ['[data-mode=heat]','[data-sys=mono]','[data-mode=cool]','#next','#reset','#play','#play','#lab','#guide']) { await page.click(sel); await page.waitForTimeout(500); }
console.log(JSON.stringify({title:await page.title(),h1:await page.textContent('h1'),errs}));
await page.screenshot({path:"/tmp/v.png"});
EOF
dev-browser run /tmp/v.js 2>&1 | tail -20

